def grade(avg):
    if avg >= 80:
        return "A+"
    elif avg >= 60:
        return "A"
    elif avg >= 40:
        return "B"
    return "F"

import unittest
from result import grade

class TestGrade(unittest.TestCase):
    def test_top_grade(self):
        self.assertEqual(grade(85), "A+")

    def test_boundaries(self):
        self.assertEqual(grade(80), "A+")
        self.assertEqual(grade(79.9), "A")
        self.assertEqual(grade(40), "B")
        self.assertEqual(grade(39.9), "F")
